    public static void run(GameController game){require(running==null,"exclusive Traveller native fixture");running=new Fixture(game);try{running.presentation();running.advancement();running.cleanse();running.buffs();running.equipmentAndGuards();running.begin();}catch(Throwable failure){try{running.close();}finally{running=null;}throw failure;}}
    public static void tick(GameController game){if(game==null||running==null)return;try{if(running.step()){running.close();running=null;SkyWars2.LOGGER.info("[check] PASS traveller (original four-piece vanilla source gear/pool/attributes; native player kill-award criterion route; all20 selective whole-layer/owned-status cleanses and11buffs; source six replacement draws/self-only sounds; real200/300tick native cadence, chest priorfalltimer/naturalexpiry, instantheal/helmet food consumption; shared guards and stop lifecycle)");}}catch(Throwable failure){try{running.close();}catch(Throwable cleanup){failure.addSuppressed(cleanup);}finally{running=null;}SkyWars2.LOGGER.error("[check] FAIL traveller",failure);}}
